css:
body {
    font-family: Courier, monospace;
    margin: 0;
    padding: 0;
    background: #fff;
}

table, tr, td {
    margin: 0 !important;
    padding: 0;
    border-spacing: 0;
    border-collapse: collapse;
}
@page {
    counter-increment: page;
    counter-reset: page 1;
}

.pageNumber::after {
    content: counter(page);
}

.totalPages::after {
    content: counter(pages);
}
.main-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    table-layout: fixed;
}

.main-table td,
.main-table th {
    padding: 0;
}

.left-40 {
    width: 70% !important;
    vertical-align: top;
    font-size: 8px;
    font-family: Courier, monospace;
}

.right-20 {
    width: 30% !important;
    vertical-align: middle;
}

.grid-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 10 5px;
    margin-right: -10px;
    padding: 0px;
}

.grid-cell {
    margin-top: -7px;
    width: 50%;
    height: 60px;
    border: 1px solid #ccc;
    text-align: center;
    vertical-align: middle;
    border-radius: 5px;
}

.nested-right-table {
    width: 100%;
    table-layout: fixed;
    margin: 5px 0px 0px -7px !important;
}

.image-cell {
    width: 60%;
}

.image-cell img {
    object-fit: cover;
}

.text-cell {
    width: 40%;
    font-size: 9px;
    font-family: sans-serif;
    line-height: 1.5;
    color: #333;
    vertical-align: middle;
    padding-left: 10px;
}

.section-combined-box {
    display: flex;
    border: 1.5px solid #888;
    border-radius: 7px 7px 0 0;
    overflow: hidden;
    height: 32px;
    font-size: 10px;
    font-family: Courier, monospace;
    text-align: center;
}

.separate-combined-box {
    display: flex;
    border: 1.5px solid #888;
    border-radius: 0px 0px 7px 7px;
    overflow: hidden;
    height: 32px;
    font-size: 10px;
    font-family: Courier, monospace;
    text-align: center;
    margin-bottom: 8px;
}

.section-inner {
    flex: 1;
    line-height: 32px;
    padding: 0 8px;
    border-right: 1px solid transparent;
}

.section-inner:last-child {
    border-right: none;
}

.section-box {
    border: 1.5px solid #888;
    height: 32px;
    border-radius: 7px 7px 0px 0px;
}

.custom-table {
    border: 1.3px solid #9d8383 !important;
    border-radius: 15px !important;
    width: 100%;
    height: 20vh;
    border-collapse: separate !important;
    overflow: hidden;
    display: table;
    table-layout: fixed;
    position: relative;
    padding: 10px;
}

.custom-table th,
.custom-table td {
    padding: 10px;
    text-align: left;
    font-size: 11px;
    border: none;
    font-family: Courier, monospace;
}

.custom-table th {
    font-size: 12px;
    color: black;
    border-bottom: 1px solid #9d8383;
    align-content: center;
}

.custom-table thead {
    border-bottom: 2px solid #9d8383;
    display: table-header-group;
}

.custom-table tbody {
    display: table-row-group;
    height: 100%;
    vertical-align: top;
}

.custom-table tfoot {
    display: table-footer-group;
    margin-top: auto;
}

.print-page-footer {
    border: 1px solid #9d8383;
    border-radius: 10px;
    margin-top: 7px;
}

.custom-table-2 {
    border: none;
    margin-top: 5px !important;
    width: 100%;
    border-collapse: separate;
    overflow: hidden;
    font-family: Arial, sans-serif;
    padding: 10px 0px 0px 0px;
}

.custom-table-2 th,
.custom-table-2 td {
    color: black;
    font-size: 12px;
    text-align: center;
    padding: 8px 12px;
}

.custom-table-2 thead th {
    height: 10px;
}

.print-format td,
.print-format th {
    padding: 1px !important;
}

.bottom-info-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: 5px;
}

.bottom-info-table td {
    vertical-align: middle;
    padding: 10px;
}

.invalid-purchase {
    width: 40%;
    text-align: center;
    font-size: 10px;
    align-content: center;
    background-color: transparent !important;
}

.invalid-purchase pre {
    background-color: transparent !important;
    font-family: Courier, monospace;
    margin: 0;
    padding: 0;
    white-space: pre;
    text-align: center;
    border: none;
    font-size: 10px;
    line-height: 1.1;
}

.qr-cell {
    width: 20%;
    text-align: center;
    vertical-align: middle;
}

.qr-cell img {
    width: 80px;
    height: 150px;
    object-fit: contain;
}

.grand-total {
    width: 40%;
    font-family: Courier, monospace;
    align-content: center;
    font-size: 11px;
    align-content: baseline;
}

.grand-total .amount {
    font-size: 11px;
    font-family: Courier, monospace;
    color: #000;
    align-content: center;
}

.qr-wrapper {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.qr-wrapper img {
    width: 80px;
    height: 80px;
    object-fit: contain;
    margin-bottom: 5px;
}

.qr-caption {
    font-size: 11px;
    color: #333;
    text-align: center;
}

@media print {
    .nested-right-table {
        margin: 0px 0px 5px 5px !important;
    }

    .print-page-footer {
        position: fixed;
        bottom: 0;
        left: 0;
        width: 100%;
        background-color: #fff;
        padding: 10px;
        box-sizing: border-box;
        text-align: center;
        font-size: 11px;
        border: 1.3px solid #9d8383;
        border-radius: 10px;
    }

    .print-page-footer .custom-table-2 {
        border: none;
        border-radius: 0px;
        margin-top: 0;
        padding-top: 10px;
        width: 100%;
    }

    .print-page-footer .custom-table-2 th,
    .print-page-footer .custom-table-2 td {
        border: none;
    }

    .print-page-footer .custom-table-2 thead th {
        border-bottom: none;
    }

    .grid-table {
        border-spacing: 10px 5px;
        margin-right: 0;
    }

    .grid-cell {
        margin-top: -7px;
    }
}
